export const EXAMPLE_DOTS_YAML = "spec: \"0.1\"\nstudy:\n  slug: dots-feedback-mratio\n  title: Accuracy feedback and metacognitive efficiency\n  approved_protocol: \"Umbrella approval for anonymous online tasks (edit to your protocol number)\"\n\nblocks:\n  consent: consent@1\n  instr: instructions@1\n  dots: dots-2afc-confidence@1\n  attn: attention-check@1\n  debrief: debrief@1\n\ndesign:\n  between:\n    feedback: [none, trialwise]\n  assignment: { method: deficit_weighted }\n\nsequence:\n  - use: consent\n    params:\n      text: |\n        You are invited to take part in a study about perceptual decisions.\n\n        The task takes about 18 minutes. Your responses are anonymous.\n        You can stop at any time by closing this window.\n\n  - use: instr\n    params:\n      pages:\n        - |\n          On each trial, two boxes of dots will flash briefly.\n\n          Press **F** if the **left** box had more dots, or **J** if the **right** box had more dots.\n        - |\n          After each choice, rate how confident you are, from 1 (**guessing**) to 6 (**certain**).\n\n  - use: dots\n    id: practice\n    params:\n      trials: 30\n      feedback: always\n      staircase: { rule: 2down1up, start_diff: 20, step: [4, 2, 1] }\n      record: false\n\n  - use: dots\n    id: main\n    params:\n      blocks: 4\n      trials_per_block: 50\n      feedback: { $cond: feedback, none: never, trialwise: always }\n      staircase: { continue_from: practice }\n\n  - use: attn\n    params:\n      item: \"To show you are reading carefully, please select 'Strongly disagree'.\"\n      correct: Strongly disagree\n\n  - use: debrief\n    params:\n      text: |\n        Thank you for taking part. This study looks at whether feedback changes how well\n        people's confidence tracks their accuracy.\n\nmeasures:\n  accuracy: { fn: mean, of: main.correct }\n  mratio: { fn: mratio, from: main }\n  d_prime: { fn: d_prime, from: main }\n  conf_sd: { fn: sd, of: main.confidence }\n  fast_rt: { fn: prop, of: main.rt, where: \"< 200\" }\n\nexclusions:\n  - { id: at_chance, when: \"accuracy < 0.60\" }\n  - { id: flat_conf, when: \"conf_sd == 0\" }\n  - { id: fast, when: \"fast_rt > 0.10\" }\n  - { id: attn_fail, when: \"attn.passed == false\" }\n\nrecruitment:\n  platform: prolific\n  max_n: 240\n  est_minutes: 18\n  reward_per_participant: 2.70\n  currency: GBP\n\nanalysis:\n  primary:\n    hypothesis: M-ratio is higher with trialwise feedback than without feedback.\n    dv: mratio\n    test: bf_ttest_independent\n    factor: feedback\n    prior: { cauchy_r: 0.707, direction: \"trialwise > none\" }\n  stopping:\n    check_every: 10\n    min_n_per_group: 30\n    max_n_per_group: 100\n    stop_when: \"bf10 >= 10 or bf10 <= 0.1\"\n  secondary:\n    - Hierarchical meta-d' (HMeta-d) by condition, reported descriptively.\n\npilot:\n  n_per_condition: 6\n  checks:\n    - { id: main_trials, expect: \"count(main) == 200\", level: blocker }\n    - { id: main_accuracy, expect: \"mean(main.correct) between 0.64 and 0.78\", level: blocker }\n    - { id: conf_use, expect: \"median(main.confidence_levels_used) >= 3\", level: warning }\n    - { id: exclusions, expect: \"exclusion_rate <= 0.25\", level: blocker }\n\nsimulation:\n  n_per_group: [30, 60, 100]\n  reps: 100\n  truth:\n    threshold: { mean: 12, sd: 4 }\n    mratio: { mean: 0.8, sd: 0.25, by: { feedback: { none: 0.80, trialwise: 0.95 } } }\n    attention_pass: 0.95\n";

export const EXAMPLE_FLANKER_YAML = "spec: \"0.1\"\nstudy:\n  slug: flanker-feedback\n  title: Error feedback and the flanker effect\n  approved_protocol: \"Umbrella approval for anonymous online tasks (edit to your protocol number)\"\n\nblocks:\n  consent: consent@1\n  instr: instructions@1\n  flanker: choice-rt@1\n  attn: attention-check@1\n  debrief: debrief@1\n\ndesign:\n  between:\n    feedback: [none, errors]\n\nsequence:\n  - use: consent\n    params:\n      text: |\n        You are invited to take part in a short study about attention.\n\n        It takes about 8 minutes. Your responses are anonymous, and you can stop at any time.\n\n  - use: instr\n    params:\n      pages:\n        - |\n          You will see a row of five arrows. Respond to the **middle** arrow only.\n\n          Press **F** if it points **left**, and **J** if it points **right**. Be fast and accurate.\n\n  - use: flanker\n    id: practice\n    params:\n      trials: 12\n      feedback: always\n      record: false\n      stimuli: &arrows\n        - { id: con_left, text: \"<<<<<\", type: congruent, correct: left }\n        - { id: con_right, text: \">>>>>\", type: congruent, correct: right }\n        - { id: inc_left, text: \">><>>\", type: incongruent, correct: left }\n        - { id: inc_right, text: \"<<><<\", type: incongruent, correct: right }\n      responses: &keys\n        - { name: left, key: f, label: \"F = left\" }\n        - { name: right, key: j, label: \"J = right\" }\n      font: mono\n\n  - use: flanker\n    id: main\n    params:\n      blocks: 2\n      trials_per_block: 64\n      feedback: { $cond: feedback, none: never, errors: errors }\n      stimuli: *arrows\n      responses: *keys\n      font: mono\n\n  - use: attn\n    params:\n      item: \"To show you are reading carefully, please select 'Strongly disagree'.\"\n      correct: Strongly disagree\n\n  - use: debrief\n    params:\n      text: |\n        Thank you. This study tests whether feedback on errors changes how much the surrounding\n        arrows slow people down (the flanker effect).\n\nmeasures:\n  accuracy: { fn: mean, of: main.correct }\n  rt_incongruent: { fn: mean, of: main.rt, filter: \"type == 'incongruent' and correct == true\" }\n  rt_congruent: { fn: mean, of: main.rt, filter: \"type == 'congruent' and correct == true\" }\n  flanker_rt: { fn: diff, a: rt_incongruent, b: rt_congruent }\n  acc_incongruent: { fn: mean, of: main.correct, filter: \"type == 'incongruent'\" }\n  acc_congruent: { fn: mean, of: main.correct, filter: \"type == 'congruent'\" }\n  flanker_acc: { fn: diff, a: acc_congruent, b: acc_incongruent }\n  timeouts: { fn: mean, of: main.timeout }\n\nexclusions:\n  - { id: low_accuracy, when: \"accuracy < 0.70\" }\n  - { id: many_timeouts, when: \"timeouts > 0.10\" }\n  - { id: attn_fail, when: \"attn.passed == false\" }\n\nrecruitment:\n  platform: prolific\n  max_n: 200\n  est_minutes: 7\n  reward_per_participant: 1.10\n  currency: GBP\n\nanalysis:\n  primary:\n    hypothesis: The flanker RT effect is smaller with error feedback than without feedback.\n    dv: flanker_rt\n    test: bf_ttest_independent\n    factor: feedback\n    prior: { cauchy_r: 0.707, direction: \"none > errors\" }\n  stopping:\n    check_every: 10\n    min_n_per_group: 25\n    max_n_per_group: 90\n    stop_when: \"bf10 >= 10 or bf10 <= 0.1\"\n\npilot:\n  n_per_condition: 5\n  checks:\n    - { id: main_trials, expect: \"count(main) == 128\", level: blocker }\n    - { id: main_accuracy, expect: \"mean(main.correct) between 0.8 and 0.99\", level: warning }\n    - { id: flanker_present, expect: \"mean(flanker_rt) >= 15\", level: warning, why: \"A flanker effect should appear; none suggests the stimuli or scoring are wrong.\" }\n    - { id: exclusions, expect: \"exclusion_rate <= 0.2\", level: blocker }\n\nsimulation:\n  n_per_group: [30, 60, 90]\n  reps: 60\n  truth:\n    choice:\n      rt: { mean: 520, sd: 70 }\n      accuracy: { mean: 0.94, sd: 0.03 }\n      effects: { incongruent: { rt: 55, accuracy: -0.05 } }\n      by: { feedback: { errors: { effects: { incongruent: { rt: 40, accuracy: -0.03 } } } } }\n";

export const EXAMPLE_CUSTOM_YAML = "spec: \"0.1\"\nstudy:\n  slug: custom-gonogo-demo\n  title: Go/no-go written as custom code\n  approved_protocol: \"Umbrella approval for anonymous online tasks (edit to your protocol number)\"\n\nblocks:\n  consent: consent@1\n  gonogo: custom-jspsych@1\n  debrief: debrief@1\n\nsequence:\n  - use: consent\n    params:\n      text: |\n        A short demonstration task. It takes about 2 minutes and your responses are anonymous.\n\n  - use: gonogo\n    params:\n      description: >-\n        Go/no-go: press the space bar for a green circle (go), do nothing for a red circle (no-go).\n        20 trials, 75% go, 1 s response window.\n      expected_rows: 20\n      est_minutes: 1.5\n      params: { n_trials: 20, go_prop: 0.75, window_ms: 1000 }\n      columns:\n        trial: integer\n        go: boolean\n        responded: boolean\n        correct: boolean\n        rt: number\n      code: |\n        const P = api.params;\n        const nGo = Math.round(P.n_trials * P.go_prop);\n        const kinds = Array.from({ length: P.n_trials }, (_, i) => i < nGo);\n        for (let i = kinds.length - 1; i > 0; i--) {\n          const j = Math.floor(api.rng() * (i + 1));\n          [kinds[i], kinds[j]] = [kinds[j], kinds[i]];\n        }\n        const circle = (c) => `<div style=\"width:120px;height:120px;border-radius:50%;background:${c};margin:auto\"></div>`;\n        const jsPsych = initJsPsych({ display_element: api.root, on_finish: () => api.done() });\n        const timeline = [{\n          type: jsPsychHtmlButtonResponse,\n          stimulus: \"<p>Press <b>SPACE</b> for a <b style='color:#15803d'>green</b> circle. Do nothing for a <b style='color:#b91c1c'>red</b> one.</p>\",\n          choices: [\"Start\"],\n        }];\n        kinds.forEach((go, i) => {\n          timeline.push({ type: jsPsychHtmlKeyboardResponse, stimulus: \"<div style='font-size:40px'>+</div>\", choices: \"NO_KEYS\", trial_duration: 400 });\n          timeline.push({\n            type: jsPsychHtmlKeyboardResponse,\n            stimulus: circle(go ? \"#16a34a\" : \"#dc2626\"),\n            choices: [\" \"],\n            trial_duration: P.window_ms,\n            on_finish: (d) => {\n              const responded = d.response !== null;\n              api.record({ trial: i, go, responded, correct: responded === go, rt: responded ? Math.round(d.rt) : null });\n            },\n          });\n        });\n        jsPsych.run(timeline);\n\n  - use: debrief\n    params:\n      text: Thanks, that's the end of the demo.\n\nmeasures:\n  go_rt: { fn: mean, of: gonogo.rt, filter: \"go == true and responded == true\" }\n  commission_rate: { fn: mean, of: gonogo.responded, filter: \"go == false\" }\n  accuracy: { fn: mean, of: gonogo.correct }\n\nexclusions:\n  - { id: low_accuracy, when: \"accuracy < 0.6\" }\n\nrecruitment:\n  platform: link\n  max_n: 20\n  est_minutes: 2\n";

